package com.alpharip.staffmod.cases.detectioncaseautolinker; public final class DetectionLink {private final String firstId,secondId,matchedKeys;private final long createdAt;public DetectionLink(String a,String b,String k,long t){if(a==null||b==null||a.equals(b))throw new IllegalArgumentException("Different case IDs required");firstId=a.compareTo(b)<0?a:b;secondId=a.compareTo(b)<0?b:a;matchedKeys=k==null?"":k;createdAt=t;}public String getFirstId(){return firstId;}public String getSecondId(){return secondId;}public String getMatchedKeys(){return matchedKeys;}public long getCreatedAt(){return createdAt;}}